"""Periodic DMA acquisition mode: cyclic fixed segments with loss reporting.

This module adds a *periodic acquisition* model on top of the same offline,
pure-software spirit as dma_ring (which keeps its original
submit/completion interface and is not modified):

* The hardware writes deterministically generated bytes into a fixed set of
  equal-size buffer *segments*, cycling forever: segment sequence number
  s (an infinite, never-wrapping software sequence) is written into slot
  s % segment_count during lap (completion generation) s // segment_count.
* The software claims completed segments through an independent read
  sequence number.  One claim may take several consecutive completed
  segments at once.  A segment still being written is never delivered.
* When the software lags the hardware by more than one full lap, the
  overwritten segments are gone.  The claim then reports the exact
  overwritten interval(s) as LostRange entries and never returns stale
  bytes from an older lap.  Loss is counted and demonstrated, not hidden
  behind a fake lossless stream.
* Ordering rule: within one logical step the hardware completes first and
  the software claims afterwards, so a segment completed in step k is
  claimable in step k (see PeriodicAcquisition.step).
* Stopping keeps already-completed segments claimable; a half-written
  segment is reported separately as PartialState and abandoned on stop.
  Restarting re-writes that same sequence number from byte 0, so the
  deterministic content contract below is preserved.

Content contract: the acquisition stream is deterministic incrementing
bytes.  The byte at infinite stream position p is p %% 256 (the byte
counter wraps naturally at 256).  Segment s therefore always contains
bytes((s * segment_size + i) %% 256 for i in range(segment_size)),
independently reproducible from the infinite sequence number alone.

Counter wraparound simulation: real hardware exposes a wrapping counter,
not an infinite sequence.  counter_modulus models that: the visible
hw_counter is hw_seq %% counter_modulus while all bookkeeping uses the
infinite sequence number, so expectations stay exact across wraps.

No threads, no hardware, no I/O; only the contract documented here is
implemented.
"""

from __future__ import annotations

from dataclasses import dataclass

from dma_ring import _as_int


class PeriodicDmaError(Exception):
    """Base class for errors raised by this module."""


class StateError(PeriodicDmaError):
    """Operation not allowed in the current run/stop state."""


@dataclass(frozen=True)
class SegmentView:
    """One delivered segment: infinite seq, lap generation, slot, bytes."""

    seq: int
    generation: int
    slot: int
    data: bytes


@dataclass(frozen=True)
class LostRange:
    """A closed interval of overwritten (unrecoverable) sequence numbers."""

    first_seq: int
    last_seq: int  # inclusive
    count: int


@dataclass(frozen=True)
class PartialState:
    """The half-written segment at the hardware frontier, if any."""

    seq: int
    slot: int
    bytes_written: int
    segment_size: int


@dataclass(frozen=True)
class ClaimResult:
    """Outcome of one claim: delivered segments, lost intervals, partial."""

    segments: tuple[SegmentView, ...]
    lost: tuple[LostRange, ...]
    partial: PartialState | None


@dataclass(frozen=True)
class StopReport:
    """Returned by PeriodicAcquisition.stop."""

    completed_pending: int        # completed but not yet claimed
    partial: PartialState | None  # abandoned half-written segment, if any
    lost_total: int               # cumulative lost segments so far


def _check_positive(value, name: str) -> int:
    value = _as_int(value, name)
    if value < 1:
        raise ValueError(f"{name}: must be >= 1, got {value}")
    return value


class PeriodicAcquisition:
    """Cyclic fixed-segment acquisition with explicit overrun reporting.

    Parameters:
        segment_count:   number of fixed buffer segments (>= 1).
        segment_size:    bytes per segment (>= 1).
        counter_modulus: optional modulus (>= 2) for the simulated wrapping
                         hardware counter exposed as hw_counter.
    """

    def __init__(self, segment_count, segment_size, *,
                 counter_modulus=None) -> None:
        self.segment_count = _check_positive(segment_count, "segment_count")
        self.segment_size = _check_positive(segment_size, "segment_size")
        if counter_modulus is not None:
            counter_modulus = _as_int(counter_modulus, "counter_modulus")
            if counter_modulus < 2:
                raise ValueError(
                    f"counter_modulus: must be >= 2, got {counter_modulus}")
        self.counter_modulus = counter_modulus
        n, size = self.segment_count, self.segment_size
        self._segments = [bytearray(size) for _ in range(n)]
        self._completed: list[int | None] = [None] * n
        self._read_seq = 0     # software claim frontier (infinite seq)
        self._hw_seq = 0       # sequence number currently being written
        self._written = 0      # bytes written into the current segment
        self._running = True
        self._lost_total = 0

    # -- introspection ----------------------------------------------------

    @property
    def running(self) -> bool:
        return self._running

    @property
    def read_seq(self) -> int:
        """Infinite sequence number the software will claim next."""
        return self._read_seq

    @property
    def hw_seq(self) -> int:
        """Infinite sequence number the hardware is writing now."""
        return self._hw_seq

    @property
    def hw_counter(self) -> int:
        """Simulated hardware counter (wraps at counter_modulus)."""
        if self.counter_modulus is None:
            return self._hw_seq
        return self._hw_seq % self.counter_modulus

    @property
    def lost_total(self) -> int:
        """Cumulative number of overwritten segments detected so far."""
        return self._lost_total

    def partial_state(self) -> PartialState | None:
        """The half-written frontier segment, or None on a boundary."""
        if self._written == 0:
            return None
        return PartialState(
            seq=self._hw_seq,
            slot=self._hw_seq % self.segment_count,
            bytes_written=self._written,
            segment_size=self.segment_size,
        )

    def status(self) -> dict:
        """Out-of-band snapshot for tests and demos (not a protocol read)."""
        return {
            "running": self._running,
            "read_seq": self._read_seq,
            "hw_seq": self._hw_seq,
            "hw_counter": self.hw_counter,
            "completed_pending": self._hw_seq - self._read_seq,
            "lost_total": self._lost_total,
            "partial": self.partial_state(),
        }

    # -- hardware side ----------------------------------------------------

    def hw_write(self, nbytes) -> None:
        """Advance the hardware by nbytes deterministic stream bytes.

        Bytes fill the current segment; each full segment is completed with
        its completion generation and the hardware moves to the next slot,
        overwriting whatever the previous lap left there.  Requires the
        acquisition to be running.
        """
        nbytes = _as_int(nbytes, "nbytes")
        if nbytes < 0:
            raise ValueError(f"nbytes: must be >= 0, got {nbytes}")
        if not self._running:
            raise StateError("hardware cannot write while stopped")
        remaining = nbytes
        while remaining > 0:
            chunk = min(remaining, self.segment_size - self._written)
            slot = self._hw_seq % self.segment_count
            base = self._hw_seq * self.segment_size + self._written
            buf = self._segments[slot]
            for k in range(chunk):
                buf[self._written + k] = (base + k) % 256
            self._written += chunk
            remaining -= chunk
            if self._written == self.segment_size:
                self._completed[slot] = self._hw_seq
                self._hw_seq += 1
                self._written = 0

    def hw_step(self) -> None:
        """Advance the hardware by exactly one full segment."""
        self.hw_write(self.segment_size)

    # -- software side ----------------------------------------------------

    def claim(self, max_segments=None) -> ClaimResult:
        """Claim up to max_segments consecutive completed segments.

        Starts at the read sequence number and walks forward: segments whose
        data is still valid are delivered; segments already overwritten by a
        newer lap are reported as LostRange and skipped (their old bytes are
        never returned); the walk stops at the first sequence number the
        hardware has not completed yet.  Works while running and while
        stopped.  max_segments=None claims everything available.
        """
        if max_segments is not None:
            max_segments = _check_positive(max_segments, "max_segments")
        n = self.segment_count
        segments: list[SegmentView] = []
        lost: list[LostRange] = []
        s = self._read_seq
        while max_segments is None or len(segments) < max_segments:
            slot = s % n
            completed = self._completed[slot]
            if completed is None or completed < s:
                break  # frontier: not completed by hardware yet
            if completed >= s + n:
                first = s
                while True:
                    s += 1
                    c = self._completed[s % n]
                    if c is None or c < s + n:
                        break
                lost.append(LostRange(first, s - 1, s - first))
                self._lost_total += s - first
                continue
            segments.append(SegmentView(
                seq=s, generation=s // n, slot=slot,
                data=bytes(self._segments[slot])))
            s += 1
        self._read_seq = s
        return ClaimResult(
            segments=tuple(segments),
            lost=tuple(lost),
            partial=self.partial_state(),
        )

    def step(self, max_segments=None) -> ClaimResult:
        """One logical step: hardware completes one segment, then claim.

        Defines the same-step ordering: the hardware completion happens
        first, so the segment completed in this step is visible to the
        claim made in this step.
        """
        self.hw_step()
        return self.claim(max_segments)

    # -- run control ------------------------------------------------------

    def stop(self) -> StopReport:
        """Stop acquisition.

        Completed-but-unclaimed segments stay claimable after the stop.  A
        half-written segment is reported in the StopReport and abandoned:
        it is never completed, delivered, or counted as lost; start()
        re-writes the same sequence number from byte 0.
        """
        if not self._running:
            raise StateError("acquisition is already stopped")
        partial = self.partial_state()
        self._written = 0  # abandon the half-written segment
        self._running = False
        return StopReport(
            completed_pending=self._hw_seq - self._read_seq,
            partial=partial,
            lost_total=self._lost_total,
        )

    def start(self) -> None:
        """Restart after stop; sequence numbers continue, not reset."""
        if self._running:
            raise StateError("acquisition is already running")
        self._running = True
